	FILE *fp=fopen("test.txt","w+");
    int pid;	//pid表示fork函数的返回值
	/**********  Begin  **********/
	pid = fork();
    if (pid == 0) {
        fputs("hello welcome!\n", fp);
    } else {
        fputs("hello world!\n", fp);
    }

	/**********  End  **********/
    fclose(fp);
	return 0;

}
